const simulation = flow.get('xySimulation');
if (!simulation?.enabled) return null;
if (context.get('xyEpoch') !== simulation.epoch) {
  context.set('xyEpoch', simulation.epoch);
  context.set('xySequence', 0);
}
const sequence = Number(context.get('xySequence') || 0) + 1
context.set('xySequence', sequence)
const sampleTime = Date.now()
const frequencyHz = 30
const makeManifest = (streamId, xUnit, yUnit, maxPoints = 1024) => ({ kind: 'xy-series-manifest', streamId, epoch: simulation.epoch + '-' + streamId.replaceAll('/', '-'), layoutVersion: 1, publishHz: frequencyHz, clock: 'monotonic-ms', maxPoints, xUnit, yUnit })
const makeSpectrum = phase => Array.from({ length: 1024 }, (_, index) => {
  const frequency = 20 * Math.pow(1000, index / 1023)
  const level = -46 + 18 * Math.sin(index / 260 + phase) + 9 * Math.sin(index / 73 + phase * 1.7)
  return [frequency, level]
})
const makeFrame = (streamId, points) => ({ kind: 'xy-series-frame', streamId, epoch: simulation.epoch + '-' + streamId.replaceAll('/', '-'), layoutVersion: 1, seq: sequence, sampleTime, points })
const message = (kind, path, streamId, payload) => ({ kind, device: 'Meter Validation', path, streamId, payload })
const spectra = ['a', 'b', 'c', 'd'].map((letter, index) => {
  const streamId = 'validation/spectrum-' + letter
  return { streamId, manifest: makeManifest(streamId, 'Hz', 'dB'), frame: makeFrame(streamId, makeSpectrum(sequence / 20 + index)) }
})
const coordinateStream = 'validation/coordinates'
const coordinates = [[116.368 + Math.sin(sequence / 16) * .014, 39.912 + Math.cos(sequence / 19) * .012], [116.405 + Math.sin(sequence / 21) * .011, 39.925 + Math.cos(sequence / 16) * .014], [116.432 + Math.sin(sequence / 18) * .009, 39.895 + Math.cos(sequence / 23) * .01], [116.389 + Math.sin(sequence / 25) * .013, 39.878 + Math.cos(sequence / 14) * .009]]
const coordinateManifest = makeManifest(coordinateStream, 'longitude', 'latitude', 16)
const coordinateFrame = makeFrame(coordinateStream, coordinates)
const manifest = sequence === 1
return [
